import { createRoute, z } from '@hono/zod-openapi'

const UserInfoSchema = z
  .object({
    avatarUuid: z.string().openapi({ description: '&#128640; Since v4.11.0\n\nAvatar UUID' }),
    displayName: z
      .string()
      .exactOptional()
      .openapi({
        deprecated: true,
        description:
          '&#128679; Deprecated since v4.11.0\n\nDisplay name\n\nuse other fields from `UserInfo` instead to combine a display name',
      }),
    email: z.string().exactOptional().openapi({ description: '&#128640; Since v4.11.0\n\nEmail ' }),
    firstName: z
      .string()
      .openapi({
        description:
          '&#128640; Since v4.11.0\n\nUser first name (mandatory if `userType` is `internal`)',
      }),
    id: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({ type: 'integer', format: 'int64', description: 'Unique identifier for the user' }),
    lastName: z
      .string()
      .openapi({
        description:
          '&#128640; Since v4.11.0\n\nUser last name (mandatory if `userType` is `internal`)',
      }),
    title: z
      .string()
      .exactOptional()
      .openapi({
        deprecated: true,
        description: '&#128679; Deprecated since v4.18.0\n\nJob title',
      }),
    userName: z
      .string()
      .openapi({
        description: '&#128640; Since v4.13.0\n\nUsername (only returned for `internal` users)',
      }),
    userType: z
      .enum(['system', 'internal', 'external', 'deleted'])
      .openapi({
        description:
          '&#128640; Since v4.11.0\n\nUser type:\n\n* `internal` - ordinary DRACOON user\n\n* `external` - external user without DRACOON account\n\n* `system` - system user (non human &#128125;)\n\n* `deleted` - deleted DRACOON user',
      }),
  })
  .openapi({
    description: 'User information',
    required: ['avatarUuid', 'firstName', 'id', 'lastName', 'userName', 'userType'],
  })
  .openapi('UserInfo')

const EncryptionInfoSchema = z
  .object({
    dataSpaceKeyState: z
      .enum(['none', 'available', 'pending'])
      .openapi({ description: 'DRACOON key state' }),
    roomKeyState: z
      .enum(['none', 'available', 'pending'])
      .openapi({ description: 'Room key state' }),
    userKeyState: z
      .enum(['none', 'available', 'pending'])
      .openapi({ description: 'User key state' }),
  })
  .openapi({
    description: 'Encryption states',
    required: ['dataSpaceKeyState', 'roomKeyState', 'userKeyState'],
  })
  .openapi('EncryptionInfo')

const NodePermissionsSchema = z
  .object({
    change: z
      .boolean()
      .openapi({
        description:
          'User / Group may update metadata of nodes: rename files and folders, change classification, etc.',
      }),
    create: z
      .boolean()
      .openapi({
        description:
          'User / Group may upload files, create folders and copy / move files to this room, overwriting is not possible.',
      }),
    delete: z
      .boolean()
      .openapi({
        description:
          'User / Group may overwrite and remove files / folders, move files from this room.',
      }),
    deleteRecycleBin: z
      .boolean()
      .openapi({
        description: 'User / Group may permanently remove files / folders from the recycle bin.',
      }),
    manage: z
      .boolean()
      .openapi({
        description:
          'User / Group may grant all of the above permissions to other users and groups independently,\n\nmay update room metadata and create / update / delete subordinary rooms, has all permissions.',
      }),
    manageDownloadShare: z
      .boolean()
      .openapi({
        description:
          'User / Group may create Download Shares for files and containers view all previously created Download Shares in this room.',
      }),
    manageUploadShare: z
      .boolean()
      .openapi({
        description:
          'User / Group may create Upload Shares for containers, view all previously created Upload Shares in this room.',
      }),
    read: z
      .boolean()
      .openapi({
        description:
          'User / Group may see all rooms, files and folders in the room and download everything, copy files from this room.',
      }),
    readRecycleBin: z
      .boolean()
      .openapi({ description: 'User / Group may look up files / folders in the recycle bin.' }),
    restoreRecycleBin: z
      .boolean()
      .openapi({
        description:
          'User / Group may restore files / folders from recycle bin - room permissions required.',
      }),
  })
  .openapi({
    description: 'Node permissions',
    required: [
      'change',
      'create',
      'delete',
      'deleteRecycleBin',
      'manage',
      'manageDownloadShare',
      'manageUploadShare',
      'read',
      'readRecycleBin',
      'restoreRecycleBin',
    ],
  })
  .openapi('NodePermissions')

type NodeType = {
  authParentId?: bigint
  branchVersion?: bigint
  children?: NodeType[]
  classification?: 1 | 2 | 3 | 4
  cntChildren?: number
  cntComments?: number
  cntDeletedVersions?: number
  cntDownloadShares?: number
  cntFiles?: number
  cntFolders?: number
  cntRooms?: number
  cntUploadShares?: number
  createdAt?: string
  createdBy?: z.infer<typeof UserInfoSchema>
  encryptionInfo?: z.infer<typeof EncryptionInfoSchema>
  expireAt?: string
  fileType?: string
  hasActivitiesLog?: boolean
  hash?: string
  id: bigint
  inheritPermissions?: boolean
  isBrowsable?: boolean
  isEncrypted?: boolean
  isFavorite?: boolean
  mediaToken?: string
  mediaType?: string
  name: string
  notes?: string
  parentId?: bigint
  parentPath?: string
  permissions?: z.infer<typeof NodePermissionsSchema>
  quota?: bigint
  recycleBinRetentionPeriod?: number
  referenceId?: bigint
  size?: bigint
  timestampCreation?: string
  timestampModification?: string
  type: 'room' | 'folder' | 'file'
  updatedAt?: string
  updatedBy?: z.infer<typeof UserInfoSchema>
}

type RoomDataType = {
  children?: RoomDataType[]
  cntDownloadShares?: number
  cntUploadShares?: number
  createdAt?: string
  createdBy?: z.infer<typeof UserInfoSchema>
  hasRecycleBin: boolean
  id: bigint
  isEncrypted: boolean
  isFavorite?: boolean
  isGranted: boolean
  name: string
  parentId?: bigint
  permissions?: z.infer<typeof NodePermissionsSchema>
  quota?: bigint
  recycleBinRetentionPeriod: number
  size?: bigint
  type?: 'room'
  updatedAt?: string
  updatedBy?: z.infer<typeof UserInfoSchema>
}

const ActiveDirectorySchema = z
  .object({
    alias: z.string().openapi({ description: 'Unique name for an Active Directory configuration' }),
    id: z.int32().openapi({ description: 'ID' }),
    isGlobalAvailable: z.boolean().openapi({ description: 'Is available for all customers' }),
  })
  .openapi({
    description: 'Active Directory information',
    required: ['alias', 'id', 'isGlobalAvailable'],
  })
  .openapi('ActiveDirectory')

const ActiveDirectoryAuthInfoSchema = z
  .object({
    items: z
      .array(ActiveDirectorySchema)
      .openapi({ description: 'List of available Active Directories' }),
  })
  .openapi({ description: 'List of Active Directories', required: ['items'] })
  .openapi('ActiveDirectoryAuthInfo')

const ActiveDirectoryConfigSchema = z
  .object({
    adExportGroup: z
      .string()
      .openapi({
        description:
          'If `userImport` is set to `true`,\n\nthe user must be member of this Active Directory group to receive a newly created DRACOON account.',
      }),
    alias: z.string().openapi({ description: 'Unique name for an Active Directory configuration' }),
    createHomeFolder: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        deprecated: true,
        description:
          "&#128679; Deprecated since v4.10.0\n\nDEPRECATED, will be ignored\n\nDetermines whether a room is created for each user that is created by automatic import (like a home folder).\n\nRoom's name will equal the user's login name.",
      }),
    homeFolderParent: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        deprecated: true,
        description:
          '&#128679; Deprecated since v4.10.0\n\nDEPRECATED, will be ignored\n\nID of the room in which the individual rooms for users will be created.',
      }),
    id: z.int32().openapi({ description: 'ID' }),
    ldapUsersDomain: z
      .string()
      .openapi({
        description: 'Search scope of Active Directory; only users below this node can log on.',
      }),
    sdsImportGroup: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description:
          'User group that is assigned to users who are created by automatic import.\n\nReset with `0`',
      }),
    serverAdminName: z
      .string()
      .openapi({
        description: 'Distinguished Name (DN) of Active Directory administrative account',
      }),
    serverIp: z.string().openapi({ description: 'IPv4 or IPv6 address or host name' }),
    serverPort: z.int32().min(0).max(65535).openapi({ description: 'Port' }),
    sslFingerPrint: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'SSL finger print of Active Directory server.\n\nMandatory for LDAPS connections.\n\nFormat: `Algorithm/Fingerprint`',
      }),
    useLdaps: z
      .boolean()
      .openapi({ description: 'Determines whether LDAPS should be used instead of plain LDAP.' }),
    userFilter: z
      .string()
      .openapi({ description: 'Name of Active Directory attribute that is used as login name.' }),
    userImport: z
      .boolean()
      .openapi({
        description:
          'Determines if a DRACOON account is automatically created for a new user\n\nwho successfully logs on with his / her AD / IDP account.',
      }),
  })
  .openapi({
    description: 'Active Directory configuration',
    required: [
      'adExportGroup',
      'alias',
      'id',
      'ldapUsersDomain',
      'serverAdminName',
      'serverIp',
      'serverPort',
      'useLdaps',
      'userFilter',
      'userImport',
    ],
  })
  .openapi('ActiveDirectoryConfig')

const ActiveDirectoryConfigListSchema = z
  .object({
    items: z
      .array(ActiveDirectoryConfigSchema)
      .openapi({ description: 'List of Active Directory configurations' }),
  })
  .openapi({ description: 'List of Active Directory configurations', required: ['items'] })
  .openapi('ActiveDirectoryConfigList')

