const AuditNodeResponseSchema = z
  .object({
    auditUserPermissionList: z
      .array(AuditUserPermissionSchema)
      .openapi({ description: 'List of assigned users with permissions' }),
    nodeCntChildren: z
      .int32()
      .openapi({ description: 'Number of direct children\n\n(no recursion; for rooms only)' }),
    nodeCreatedAt: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ description: 'Creation date' }),
    nodeCreatedBy: UserInfoSchema.exactOptional(),
    nodeHasActivitiesLog: z
      .boolean()
      .default(true)
      .exactOptional()
      .openapi({ description: 'Is activities log active (for rooms only)' }),
    nodeHasRecycleBin: z
      .boolean()
      .exactOptional()
      .openapi({
        deprecated: true,
        description:
          '&#128679; Deprecated since v4.10.0\n\nIs recycle bin active (for rooms only)\n\nRecycle bin is always on (disabling is not possible).',
      }),
    nodeId: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({ type: 'integer', format: 'int64', description: 'Node ID' }),
    nodeIsEncrypted: z.boolean().exactOptional().openapi({ description: 'Encryption state' }),
    nodeName: z.string().openapi({ description: 'Node name' }),
    nodeParentId: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'Parent node ID (room or folder)',
      }),
    nodeParentPath: z
      .string()
      .openapi({ description: 'Parent node path\n\n`/` if node is a root node (room)' }),
    nodeQuota: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({ type: 'integer', format: 'int64', description: 'Quota in byte' }),
    nodeRecycleBinRetentionPeriod: z
      .int32()
      .min(0)
      .max(9999)
      .exactOptional()
      .openapi({ description: 'Retention period for deleted nodes in days' }),
    nodeSize: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({ type: 'integer', format: 'int64', description: 'Node size in byte' }),
    nodeUpdatedAt: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ description: 'Modification date' }),
    nodeUpdatedBy: UserInfoSchema.exactOptional(),
  })
  .openapi({
    description: 'Audit node report',
    required: [
      'auditUserPermissionList',
      'nodeCntChildren',
      'nodeId',
      'nodeName',
      'nodeParentPath',
    ],
  })
  .openapi('AuditNodeResponse')

