const PendingAssignmentSchema = z
  .object({
    groupId: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'Unique identifier for the group',
      }),
    roomId: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({ type: 'integer', format: 'int64', description: 'Room ID' }),
    roomName: z.string().openapi({ description: 'Room name' }),
    state: z
      .enum(['ACCEPTED', 'DENIED', 'WAITING'])
      .openapi({ description: 'Acceptance state:\n\n* `ACCEPTED`\n\n* `WAITING`\n\n* `DENIED`' }),
    userId: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({ type: 'integer', format: 'int64', description: 'Unique identifier for the user' }),
  })
  .openapi({
    description: 'Pending assignment information',
    required: ['groupId', 'roomId', 'roomName', 'state', 'userId'],
  })
  .openapi('PendingAssignment')

