export const getV4DownloadsAvatarUserIdUuidRoute = createRoute({
  method: 'get',
  path: '/v4/downloads/avatar/{user_id}/{uuid}',
  tags: ['downloads'],
  summary: 'Download avatar',
  description:
    "<h3 style='padding: 5px; background-color: #F6F7F8; border: 1px solid #AAA; border-radius: 5px; display: table-cell;'>&#128640; Since v4.11.0</h3>\n\n### Description:\nDownload avatar for given user ID and UUID.\n\n### Precondition:\nValid UUID.\n\n### Postcondition:\nStream is returned.\n\n### Further Information:\nNone.",
  operationId: 'downloadAvatar',
  request: {
    params: z.object({
      user_id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            description: 'User ID',
            in: 'path',
            name: 'user_id',
            required: true,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
      uuid: z
        .string()
        .openapi({
          param: {
            description: 'UUID of the avatar',
            in: 'path',
            name: 'uuid',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/octet-stream': {
          schema: z.string(),
          examples: {
            '0': {
              summary: 'Avatar response',
              description: '`application/octet-stream` is returned',
              value: '[... byte content ...]',
            },
          },
        },
      },
    },
    400: {
      description: 'Bad Request',
      content: {
        'application/octet-stream': {
          schema: ErrorResponseSchema,
          examples: {
            '-80000': {
              summary: 'Mandatory fields cannot be empty',
              description: '\n* [-80000] Mandatory fields cannot be empty',
              value: {
                code: 400,
                debugInfo: 'Mandatory fields cannot be empty',
                errorCode: -80000,
                message: 'Bad Request',
              },
            },
            '-80002': {
              summary: 'Invalid number',
              description: '\n* [-80002] Invalid number',
              value: {
                code: 400,
                debugInfo: 'Invalid number',
                errorCode: -80002,
                message: 'Bad Request',
              },
            },
          },
        },
      },
    },
    404: {
      description: 'Not Found',
      content: {
        'application/octet-stream': {
          schema: ErrorResponseSchema,
          examples: {
            '-70028': {
              summary: 'Avatar not found',
              description: '\n* [-70028] Avatar not found',
              value: {
                code: 404,
                debugInfo: 'Avatar not found',
                errorCode: -70028,
                message: 'Not Found',
              },
            },
          },
        },
      },
    },
    406: {
      description: 'Not Acceptable',
      content: {
        'application/octet-stream': {
          schema: ErrorResponseSchema,
          examples: {
            null: {
              summary: 'Content type not acceptable',
              description: 'Acceptable Content-Types are: `[application/octet-stream]`',
              value: {
                code: 406,
                debugInfo: "Content type '...' not acceptable. Acceptable Content-Types are: [...]",
                errorCode: null,
                message: 'Not Acceptable',
              },
            },
          },
        },
      },
    },
  },
  security: [],
})

